-- Baseline: exact copy of the original data/shop.db as provided (schema + 24 books + 16 orders).
-- Applied by migrate.js only when the database has no Books table yet (tests, CI, db:reset).
-- Generated with: sqlite3 data/shop.db .dump (transaction, pragma and sqlite_sequence lines removed).
-- Do not edit: schema changes belong in migrations/.
CREATE TABLE Books (
    ID          INTEGER PRIMARY KEY AUTOINCREMENT,
    Name        TEXT NOT NULL,
    Description TEXT,
    Author      TEXT NOT NULL,
    CoverPath   TEXT                 -- short relative path, e.g. pictures/dracula.jpg
);
CREATE TABLE Orders (
    ID      INTEGER PRIMARY KEY AUTOINCREMENT,
    Address TEXT NOT NULL,
    Name    TEXT NOT NULL,
    BookId  INTEGER NOT NULL REFERENCES Books(ID) ON DELETE RESTRICT
);
CREATE INDEX idx_orders_bookid ON Orders(BookId);
